\begin{array}{l} \leq f _ {0} (\mathbf {x} ^ {*}) + \sum_ {i = 1} ^ {m} \lambda_ {i} ^ {*} f _ {i} (\mathbf {x} ^ {*}) + \sum_ {j = 1} ^ {p} \nu_ {j} ^ {*} h _ {j} (\mathbf {x} ^ {*}) \\ \leq f _ {0} (\mathbf {x} ^ {*}) \end{array}\tag{25.16}

(25.17)

